#include <Trade\Trade.mqh>  // Inclusão da biblioteca de negociação

CTrade trade; // Criando uma instância da classe CTrade para gerenciar operações

// Função para verificar o spread
double GetSpread() {
    double ask = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bid = SymbolInfoDouble(Symbol(), SYMBOL_BID);

    if (Ask == 0 || Bid == 0) return -1;

    return (ask - bid) / _Point;
}

// Função para verificar volatilidade com base no ATR (Average True Range)
double GetATR(int period = 14) {
    return iATR(Symbol(), PERIOD_CURRENT, period, 0);
}

// Função para verificar se a vela atual é significativa (filtro para evitar consolidação)
bool IsValidCandle(double bodySize, double atr) {
    if (atr <= 0) return false;
    return bodySize > atr * 0.2; // Tamanho do corpo da vela deve ser maior que 20% do ATR
}

// Função para detectar rompimento de máxima/mínima da vela anterior
bool IsBreakout(double currentHigh, double currentLow, double prevHigh, double prevLow) {
    return (currentHigh > prevHigh + _Point || currentLow < prevLow - _Point);
}

// Função principal executada a cada tick
void OnTick() {
    // Configurações da estratégia
    double lotSize = 0.01;
    double takeProfitPips = 10; // Lucro curto para scalping
    double stopLossPips = 20;   // Stop Loss baseado em volatilidade
    double trailingStopPips = 10.0; // Trailing Stop para garantir lucros
    double spreadThreshold = 10.0;  // Evitar operar com spread acima de 10 pips

    // Verificações pré-operação
    if (_PositionOpenCount >= PositionsTotal()) return; // Sem slots disponíveis
    if (PositionsTotal() == 0) return; // Nenhuma posição aberta

    // Obter preços de compra e venda (ask e bid)
    double askPrice = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bidPrice = SymbolInfoDouble(Symbol(), SYMBOL_BID);

    if (askPrice == 0 || bidPrice == 0) {
        Print("Preço inválido - não operando");
        return;
    }

    // Evitar operações com spread elevado
    double currentSpread = GetSpread();
    if (currentSpread < 0 || currentSpread > spreadThreshold) {
        // PrintDebug("Spread: ", DoubleToString(currentSpread, _Digits), "pips | Threshold: ", spreadThreshold);
        return; // Não executar ordens
    }

    // Preço da vela atual e anterior (atual bar e 1 bar atrás)
    double open1 = iOpen(NULL, PERIOD_CURRENT, 0);
    double close1 = iClose(NULL, PERIOD_CURRENT, 0);
    double low1 = iLow(NULL, PERIOD_CURRENT, 0);
    double high1 = iHigh(NULL, PERIOD_CURRENT, 0);

    double open2 = iOpen(NULL, PERIOD_CURRENT, 1);
    double close2 = iClose(NULL, PERIOD_CURRENT, 1);
    double low2 = iLow(NULL, PERIOD_CURRENT, 1);
    double high2 = iHigh(NULL, PERIOD_CURRENT, 1);

    double atr = GetATR(); // Calcular o ATR atual

    // Verificação de segurança
    if (atr <= 0) {
        Print("ATR inválido - não operando", atr);
        return;
    }

    // Tamanho do corpo da vela atual
    double bodySize = MathAbs(close1 - open1);

    // Verificar se a vela atual é válida para scalping
    if (!IsValidCandle(bodySize, atr)) {
        return; // Não operar se a vela for muito pequena
    }

    // Verificar rompimento de máxima/mínima da vela anterior
    if (IsBreakout(high1, low1, high2, low2)) {
        MqlTradeRequest request;
        MqlTradeResult result;
        ZeroMemory(request);
        ZeroMemory(result);

        DebugPrint("Breakout detectado - tentando abrir ordem");

        // Regras de compra (rompimento de alta)
        if (close1 > high2 && bodySize > atr * 0.5) { 
            DebugPrint("TENTANDO COMPRAR...");

            request.action = TRADE_ACTION_DEAL;
            request.symbol = Symbol();
            request.volume = lotSize;
            request.type = ORDER_TYPE_BUY;
            request.price = NormalizeDouble(askPrice, _Digits);
            request.tp = NormalizeDouble(askPrice + takeProfitPips * _Point, _Digits);
            request.sl = NormalizeDouble(askPrice - stopLossPips * _Point, _Digits);
            request.deviation = 3;
            request.magic_number = 100;
            request.comment = "ATR Breakout Buy";

            if (OrderSend(request, result))
                Print("✓ Ordem de Compra Executada na tick", GetLastError());
            else
                Print("✗ Erro ao executar a ordem de compra: Código = ", GetLastError());
        }

        // Regras de venda (rompimento de baixa)
        else if (close1 < low2 && bodySize > atr * 0.5) { 
            DebugPrint("TENTANDO VENDER...");

            request.action = TRADE_ACTION_DEAL;
            request.symbol = Symbol();
            request.volume = lotSize;
            request.type = ORDER_TYPE_SELL;
            request.price = NormalizeDouble(bidPrice, _Digits);
            request.tp = NormalizeDouble(bidPrice - takeProfitPips * _Point, _Digits);
            request.sl = NormalizeDouble(bidPrice + stopLossPips * _Point, _Digits);
            request.deviation = 3;
            request.magic_number = 100;
            request.comment = "ATR Breakout Sell";

            if (OrderSend(request, result))
                Print("✓ Ordem de Venda Executada na tick", GetLastError());
            else
                Print("✗ Erro ao executar a ordem de venda: Código = ", GetLastError());
        }
    }

    // Gestão de posições abertas com Trailing Stop
    int positionsCount = PositionsTotal();
    for (int i = positionsCount - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if (PositionSelectByTicket(ticket)) {
            double positionType = PositionGetInteger(POSITION_TYPE);
            double profit = PositionGetDouble(POSITION_PROFIT);
            double openPrice = PositionGetDouble(POSITION_PRICE_OPEN);
            double priceOpen = PositionGetDouble(POSITION_PRICE_OPEN);

            double currentPrice = (positionType == ORDER_TYPE_BUY) ? askPrice : bidPrice;

            // Verificar Se Trade ainda está dentro do SL/TP
            bool isInsideTP = true;
            if (positionType == ORDER_TYPE_BUY && currentPrice > PositionGetDouble(POSITION_TP)) {
                isInsideTP = false;
            }
            if (positionType == ORDER_TYPE_SELL && currentPrice < PositionGetDouble(POSITION_SL)) {
                isInsideTP = false;
            }

            if (!isInsideTP) continue;

            // Ajustar o Trailing Stop para POSIÇÕES de compra
            if (positionType == ORDER_TYPE_BUY) {
                double newSL = NormalizeDouble(currentPrice - trailingStopPips * _Point, _Digits);
                if (newSL > PositionGetDouble(POSITION_SL) && !trade.PositionModify(ticket, newSL, PositionGetDouble(POSITION_TP))) {
                    Print("✗ Falha ao ajustar Trailing Stop para compra (ticket=)", ticket, ", erro =", GetLastError());
                }
                else {
                    Print("Trailing Stop ajustado para posição de compra: ", DoubleToString(newSL, _Digits));
                }
            }

            // Ajustar o Trailing Stop para POSIÇÕES de venda
            else if (positionType == ORDER_TYPE_SELL) {
                double newSL = NormalizeDouble(currentPrice + trailingStopPips * _Point, _Digits);
                if (newSL < PositionGetDouble(POSITION_SL) && !trade.PositionModify(ticket, newSL, PositionGetDouble(POSITION_TP))) {
                    Print("✗ Falha ao ajustar Trailing Stop para venda (ticket=)", ticket, ", erro =", GetLastError());
                }
                else {
                    Print("Trailing Stop ajustado para posição de venda: ", DoubleToString(newSL, _Digits));
                }
            }
        }
    }
}
